import { mkdtempSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';

import { DuckDBInstance } from '@duckdb/node-api';

const extensionDir = mkdtempSync(join(tmpdir(), 'nao-ext-'));
const dataDir = mkdtempSync(join(tmpdir(), 'nao-data-'));
const outsideDir = mkdtempSync(join(tmpdir(), 'nao-outside-'));

// Stand in for the Docker build step.
{
	const instance = await DuckDBInstance.create(':memory:', { extension_directory: extensionDir });
	const connection = await instance.connect();
	await connection.run('INSTALL excel');
	await connection.run('LOAD excel');
	await connection.run(
		`COPY (SELECT 'EU' AS region, 10 AS amount UNION ALL SELECT 'US', 32) TO '${join(dataDir, 'sales.xlsx')}' WITH (FORMAT xlsx)`,
	);
	connection.closeSync();
	instance.closeSync();
	console.log('build step: installed excel and wrote a workbook');
}

// Pretend the machine has no home-directory extension cache and no network.
process.env.HOME = mkdtempSync(join(tmpdir(), 'nao-empty-home-'));

const instance = await DuckDBInstance.create(':memory:', { extension_directory: extensionDir });
const connection = await instance.connect();

await connection.run('LOAD excel');
await connection.run(`SET allowed_directories = ['${dataDir}']`);
await connection.run('SET enable_external_access = false');
await connection.run('SET lock_configuration = true');

const attempt = async (label, sql) => {
	try {
		const reader = await connection.runAndReadAll(sql);
		console.log(`ALLOWED  ${label.padEnd(24)} ${JSON.stringify(reader.getRowObjectsJson())}`);
	} catch (error) {
		console.log(`BLOCKED  ${label.padEnd(24)} :: ${error.message.split('\n')[0].slice(0, 96)}`);
	}
};

await attempt('read_xlsx in the jail', `SELECT * FROM read_xlsx('${join(dataDir, 'sales.xlsx')}')`);
await attempt('read_xlsx outside', `SELECT * FROM read_xlsx('${join(outsideDir, 'nope.xlsx')}')`);
await attempt('write a workbook out', `COPY (SELECT 1 AS a) TO '${join(outsideDir, 'leak.xlsx')}' WITH (FORMAT xlsx)`);
await attempt('install another ext', 'INSTALL spatial');

connection.closeSync();
instance.closeSync();
for (const dir of [extensionDir, dataDir, outsideDir]) {
	rmSync(dir, { recursive: true, force: true });
}

